def round_half_to_even(n):
    """
    Round half to even (also known as “bankers rounding”).

    :param n: The number to be rounded.
    :return: The rounded number.
    """

    if n < 0:
        return -round_half_to_even(-n)
    elif n > 0:
        return int(n + 0.5)
    else:
        return 0

