import functools

class LfuCache:
    def __init__(self, maxsize=128, typed=False):
        """Decorator to wrap a function with a memoizing callable that saves
        up to `maxsize` results based on a Least Frequently Used (LFU)
        algorithm.

        """
        self.cache = OrderedDict()
        self.limit = maxsize

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items())) if typed else args
            if key in self.cache:
                #update count only after retrieving it
                self.cache[key] = (self.cache[key][0] + 1, self.cache[key][1])
            else:
                if len(self.cache) >= self.limit:
                    #Discard least recently used key-value pair
                    self.cache.popitem(last=False)
                self.cache[key] = (1, func(*args, **kwargs))

            return self.cache[key][1]

        return wrapper

