class BaseCacheExample(LRUCache):
    def get(self, key: CacheKey, default: Optional[Any] = None) -> Optional[Any]:
        if key in self.cache:
            return self.cache[key]
        return default

    def put(self, key: CacheKey, value: Any) -> None:
        if len(self.cache) >= self.maxsize:
            self.cache.popitem(last=False)  # remove the least recently used item
        self.cache[key] = value

class LFUCache(BaseCacheExample):
    def __init__(self, maxsize=128, typed=False, *args, **kwargs):
        super().__init__(maxsize=maxsize, *args, **kwargs)
        self.key_counts = {}
        self.freqs = {}

    def get(self, key: CacheKey, default: Optional[Any] = None) -> Optional[Any]:
        if key not in self.cache:
            return default
        self.increment_freq(key)
        return self.cache[key]

    def put(self, key: CacheKey, value: Any) -> None:
        if key in self.cache:
            self.increment_freq(key)
        else:
            for freq in [self.freqs.get(key, 0), 1]:
                if freq not in self.freqs:
                    self.freqs[freq] = []
                self.freqs[freq].append(key)
                self.key_counts[key] = freq
                break
        super().put(key, value)

    def increment_freq(self, key: CacheKey):
        self.key_counts[key] += 1
        if self.key_counts[key] in self.freqs:
            self.freqs[self.key_counts[key]].remove(key)
        if self.key_counts[key] - 1 in self.freqs and key in self.freqs[self.key_counts[key] - 1]:
            self.freqs[self.key_counts[key] - 1].append(key)
        else:
            self.freqs[self.key_counts[key] - 1] = [key]

