def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    def trace(current_level, current_path, path_so_far):
        if current_level > max_level:
            return path_so_far
        frame = current_path[current_level]
        if frame.f_code.co_filename == e.__traceback__.tb_lineno:
            return trace(current_level + 1, current_path, path_so_far)
        return trace(current_level, current_path, frame.f_code.co_filename + ' ' + str(frame.f_lineno) + '\n' + path_so_far)

    if not isinstance(e, Exception):
        raise ValueError("Input must be an exception: " + type(e).__name__)

    path = trace(0, e.__traceback__.tb_frames, "")
    return path

