def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    return sorted(classes)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    if not classes:
        return []

    seen = set()
    result = []

    for cls in classes:
        while cls in seen:
            cls = cls if cls in cls.ancestors else None
        if cls:
            seen.add(cls)
            result.append(cls)

    return result

