    else:
        result = {}
        for key in d1:
            if key not in d2 or d2[key] != d1[key]:
                result[key] = d1[key]
            elif isinstance(d1[key], dict) and isinstance(d2[key], dict) and level > 0:
                sub_result = difference(d1[key], d2[key], level-1)
                if sub_result:
                    result[key] = sub_result
        return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict):
        return {d1: d1}

    diff = {}
    for key, value in d1.items():
        if key not in d2 or (isinstance(value, dict) and value != difference(d2[key], d1, level)):
            diff[key] = value

    if level > 0:
        for key, value in diff.items():
            if isinstance(value, dict):
                diff[key] = difference(value, d2, level-1)

    return diff

"""Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        for bin in self.bin_edges:
            if bin[0] <= coord <= bin[1]:
                self.bins[bin[1] - min(bin)] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    x, y = coord
    for val, bin in self.bins:
        if x >= bin[0] and x < bin[1]:
            self.count[val] += weight
            self.binsum[val] += weight * (y - bin[0])

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages

    # All valid characters for a label
    valid_characters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_"

    for key, value in labels.items():
        try:
            if isinstance(value, str):
                for char in value:
                    if char not in valid_characters:
                        raise ValidationError([
                            {
                                value: f"Invalid character '{char}' in label key '{key}'. Only valid characters are alphanumeric, or underscores."
                            }
                        ])
            elif isinstance(value, list):
                for item in value:
                    if not isinstance(item, str):
                        raise ValidationError([
                            {
                                value: "Invalid item in label value list. All items must be strings."
                            }
                        ])
                    for char in item:
                        if char not in valid_characters:
                            raise ValidationError([
                                {
                                    item: f"Invalid character '{char}' in label value '{item}'. Only valid characters are alphanumeric, or underscores."
                                }
                            ])
        except ValidationError as err:
            raise ValidationError(err.messages)

