    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    if not isinstance(labels, dict):
        raise ValueError("Labels must be a dictionary")

    errors = []
    for key, value in labels.items():
        if isinstance(key, str):
            key_re = AnyLabelRegex[key]
        else:
            key_re = AnyLabelRegex[Attrib.KEY]
        if not key_re.match(key):
            errors.append({"key": key, "value": "expected string or bytes-like object"})

        if isinstance(value, list):
            for elem in value:
                if not isinstance(elem, str):
                    errors.append({"key": key, "value": "expected string or bytes-like object"})
        elif not isinstance(value, str):
            errors.append({"key": key, "value": "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if resource['observer_schema'] is None:
            resource['observer_schema'] = {
                'apiVersion': 'krake.io/' + krake.version,
                'kind': 'Observer',
                'metadata': {
                    'name': resource['name'] + '-default_observer'
                },
                'spec': {
                    'mode': 'disabled',
                    'parameters': {},
                    'resources': [
                        {
                            'resources': ['*'],
                            'wlq': '1'
                        }
                    ],
                    'template': {
                        'template': {
                            'parameters': {},
                            'spec': {}
                        }
                    }
                }
            }
    return app

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schemas = {}

    for resource in app.spec.manifest:
        if resource.type not in default_schemas:
            default_schemas[resource.type] = deepcopy(resource.schema)
            default_schemas[resource.type].update({"kind": resource.type})

    for resource_type, schema in default_schemas.items():
        schema["title"] = f"Default Observer Schema for Kubernetes {resource_type}"
        schema["description"] = f"This schema provides default observer logic for Kubernetes resources of type {resource_type}."

    return default_schemas

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """


        if not path/.last_component().endswith(('.yaml', '.yml', '.json', '.py', '.pyo', '.pyc', '.pyd')):
            raise ValueError("Invalid file type encountered in path.")
        if not path.exists():
            raise FileNotFoundError("File or directory does not exist.")
        try:
            if path.is_dir():
                if not path.name.endswith('-root`'):
                    raise ValueError("Directory name must end with '-root' to be considered an OCFL root object.")
                if not all(child.get_attribute_str(Attrib.DIRECTORY_ID) for child in path.iterdescendants(alt=['.properties', '.py'])):
                    raise ValueError("All Python files or directories in the root directory must have a directory ID.")
                subprojects = [subdir for subdir in path.iterdescendants(alt=['.properties', '.py']) if '-project' in subdir.name]
                for subproject in subprojects:
                    if not subproject.get_attribute_str(Attrib.DIRECTORY_ID):
                        raise ValueError("All subprojects must have a directory ID.")
            elif path.is_file():
                if '-json' not in path.name:
                    raise ValueError("Invalid file name encountered in path.")
                if path.suffix not in ['.json']:
                    raise ValueError("Invalid file type encountered in path.")
                self.json.load(path)
        except Exception as e:
            print(f"Error validating {path}: {e}")
            return False

        return \
                   "Valid OCFL object at path or pyfs root."

