def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    spec_version = inventory.type.value[1]
    if not self.spec_version:
        if not spec_version:
            if extract_spec_version:
                raise ValueError("Inventory must have a type value to determine the specification version.")
            else:
                raise AssertionError("Inventory must have a type value to validate.")
        else:
            if self.spec_version != spec_version:
                raise ValueError("Inventory type value does not match the stored specification version.")
    else:
        if self.spec_version != spec_version:
            raise ValueError("Inventory type value mismatch between stored and given version.")

