def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used.

        Arguments:
            manifest_files (list): List of manifest files
            digests_used (list): List of digests that are used
        """
        # Create a dictionary to store the actual digests present in each manifest file
        manifest_digests = {manifest.filename: {digest: False for digest in manifest.digests} for manifest in manifest_files}

        # Check for each digest in the manifest files
        for manifest_file in manifest_files:
            with open(manifest_file, 'r') as file:
                for line in file:
                    # Check if the line contains a digest
                    for digest in manifest.digests:
                        if digest in line:
                            manifest_digests[manifest_file][digest] = True

        # Compare the actual digests with the digests used
        for digest in digests_used:
            if digest not in manifest_digests or not manifest_digests[manifest_files[0].filename][digest]:
                raise FileNotFoundError("Digest " + digest + " is required but not found in any of the manifest files.")

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""

        # Load the manifest
        with open(manifest_files[0], 'r') as file:
            manifest = json.load(file)

        # Get all needed digests from the manifest
        needed_digests = set()
        for digest in manifest['digests']:
            needed_digests.add(digest['path'])

        # Check if the digests are present
        for manifest_file in manifest_files[1:]:
            with open(manifest_file, 'r') as file:
                manifest = json.load(file)

            for digest in manifest['digests']:
                if digest['path'] not in needed_digests:
                    raise ValueError(f"Digest {digest['path']} is not present in the manifest.")
                if digest['path'] in digests_used:
                    raise ValueError(f"Digest {digest['path']} is already used in another file.")

        # Check if the digests are used
        for digest in needed_digests:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is in the manifest but un used.")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
    """
    if not prior:
        raise ValueError("Invalid prior version, prior should not be None")
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Invalid prior version, prior should be an InventoryValidator object")
    if not self.is_consistent(prior):
        raise ValueError("Current inventory object does not match the prior version")

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise TypeError("Argument 'prior' must be an InventoryValidator object.")

        if not self.isValid() or prior.isValid():
            return False

        if not self.inventory_count == prior.inventory_count:
            return False

        if not self.inventory_format == prior.inventory_format:
            return False

        for e in self:
            if not e.validate_as_prior_version(prior[e]):
                return False

        for e in prior:
            if not e.validate_as_prior_version(self[e]):
                return False

        return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior must be an InventoryValidator object")

    if self.inventory == prior.inventory:
        raise ValueError("Inventory ID mismatch")

    if self.house != prior.house:
        raise ValueError("HouseMismatch, current host ID: " + str(self.house) + "; prior host ID: " + str(prior.house))

    if self.date == prior.date:
        raise ValueError("Date mismatch, current date: " + str(self.date) + "; prior date: " + str(prior.date))

    if self.status == prior.status:
        raise ValueError("Status mismatch, current status: " + self.status + "; prior status: " + prior.status)

    return True

