def _extract_number_and_supplement_from_issue_element(issue):
    import re

    pattern = r'^(?P<number>\d+)(?: \((?P<supplement>.*)\))?$'
    match = re.match(pattern, issue)

    if match:
        number = int(match.group('number'))
        supplement = match.group('supplement')
        return number, supplement
    else:
        raise ValueError(f"Invalid format for issue: {issue}")

