def absorb(self, args):
    from collections import deque
    from logic import or_, and_, not_

    new_args = deque()

    for expr in args:
        # Apply absorption
        new_expr = and_(expr, or_)

        # Apply negative absorption
        if new_expr:
            new_expr = and_(new_expr, not_(expr))

        new_args.append(new_expr)

    return list(new_args)

