        if isinstance(arg, Absorption):
            absorbing.append(arg)
        elif isinstance(arg, AbsorptionNegative):
            non_absorbing.append(arg)
        else:
            non_absorbing.append(arg)

    return absorbing + non_absorbing

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if arg & (arg | self) == arg:
            result.append(arg)
        elif arg | (arg & self) == arg:
            result.append(arg)
        elif arg & (~arg | self) == arg & self:
            result.append(arg)
        elif arg | (~arg | self) == arg | self:
            result.append(arg)
        else:
            result.append(arg)
    return result

