def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if sys.version_info[0] < 3:
        return lambda: namefunc().encode('utf-8')
    else:
        return namefunc()

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3 it used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] < 3:
        # Python 2
        return namefunc
    else:
        # Python 3
        def decorator(tzname):
            def wrapper(*args, **kwargs):
                return tzname(*args, **kwargs).encode('latin-1', errors='replace')
            return wrapper
        return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys

    if sys.version_info[0] == 2 and sys.version_info[1] < 7:
        for name in ['tzname', 'timezone']:
            setattr(__builtin__, name, lambda * args: bytes(namefunc(*args)))

