def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        commands = [commands]

    result = []

    for command in commands:
        try:
            import subprocess
            process = subprocess.Popen([command], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=env, universal_newlines=True)
            output, error = process.communicate(input=args, timeout=10)

            if output:
                result.append(output.strip())

            if error:
                if not hide_stderr:
                    result.append(f"Error: {error.strip()}")
            else:
                if verbose:
                    print(f"Command({command}) exited with exit code: {process.returncode}")

            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, command)

        except FileNotFoundError:
            result.append(f"FileNotFoundError: command '{command}' not found")
        except subprocess.CalledProcessError as e:
            result.append(f"CalledProcessError: {e.output.strip()}")
        except Exception as e:
            result.append(f"An error occurred: {str(e)}")

    return result

