                print(e.stderr.strip())
        return None

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    command_list = []
    for cmd in commands:
        # Handle any arguments wrapping in quotes and formatting them correctly for the terminal
        cmd_args = [arg.replace('"', '\\"') for arg in args[cmd]]
        command_list.append(f"{cmd} {' '.join(cmd_args)}")

    if verbose:
        print(f"Executing: {' '.join(command_list)}")

    process = subprocess.Popen(command_list, shell=False, cwd=cwd, env=env, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    stdout, stderr = process.communicate()

    if process.returncode != 0:
        if hide_stderr:
            print(stderr.strip())
        else:
            # Print an error message indicating that the command was not successful, and include the stderr output
            raise subprocess.CalledProcessError(process.returncode, ' '.join(command_list), f"Command failed: {stderr.strip()}")

    return stdout.strip()

