def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
        """
    num_objects = 0
    good_objects = 0

    # Check root object
    root_object = self.root_object
    if not root_object:
        if show_warnings:
            print("No root object found.")
        return num_objects, good_objects

    num_objects += 1
    if validate_objects:
        valid = root_object.validate()
        if valid:
            good_objects += 1
            if show_warnings:
                print("Root object is valid.")
        else:
            if show_warnings:
                print("Root object is invalid.")
            return num_objects, good_objects

    # Check children
    for child in root_object.children:
        num_objects += 1
        if validate_objects:
            valid = child.validate()
            if valid:
                good_objects += 1
                if show_warnings:
                    print("Child object is valid.")
            else:
                if show_warnings:
                    print("Child object is invalid.")
                return num_objects, good_objects

    # Check digests if enabled
    if check_digests:
        for digest in root_object.digests:
            num_objects += 1
            if validate_objects:
                valid = digest.validate()
                if valid:
                    good_objects += 1
                    if show_warnings:
                        print("Digest is valid.")
                else:
                    if show_warnings:
                        print("Digest is invalid.")
                    return num_objects, good_objects

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # validate each object nested within the storage root
    for obj in self:
        num_objects += 1
        if validate_objects:
            if obj.validate():
                good_objects += 1
                if show_warnings:
                    print(f"Checked object {obj.id} (valid)")

    if check_digests:
        # verify if all objects use consistent digests
        for obj in self:
            if obj.digest:
                if num_objects > 1 and obj.digest != self.digest:
                    print("Inconsistent digests for some objects. Ensure all objects have the same digest.")
                    return num_objects, num_objects

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        for obj in self.tree.descendants():
            if validate_objects:
                if obj.validate() == False:
                    if show_warnings:
                        print("Invalid object:", obj, "Check failed")
                    num_objects += 1
                else:
                    if show_warnings:
                        print("Valid object:", obj)
                    good_objects += 1
            else:
                num_objects += 1

        if show_warnings:
            print("Total objects checked:", num_objects, "Valid objects:", good_objects)

        return num_objects, good_objects

