                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged = []
    for key, value in nodes:
        if key in merged:
            if isinstance(value, MappingNode):
                if isinstance(merged[key], MappingNode):
                    merged[key].update(value)
                else:
                    merged[key] = value
            else:
                merged[key] = value
        else:
            merged.append((key, value))
    return merged

from typing import List, Tuple

def deep_merge_nodes(nodes: List[Tuple['ruamel.yaml.nodes.ScalarNode', 'ruamel.yaml.nodes.MappingNode' | ...]]) -> List[Tuple['ruamel.yaml.nodes.ScalarNode', 'ruamel.yaml.nodes.MappingNode' | ...]]:
    result = []
    for key, value in nodes:
        existing_value = None
        for existing_key, existing_value in result:
            if key == existing_key:
                break
        else:
            result.append((key, value))
            continue

        if isinstance(value, MappingNode):
            if isinstance(existing_value, MappingNode):
                for existing_key, existing_value in existing_value.items():
                    if existing_key in value:
                        value[existing_key] = deep_merge_nodes([(existing_key, existing_value)]).pop()
            else:
                result[-1] = (key, value)
        else:
            existing_value = value

    return result

