import inspect

def parse_arguments(*unparsed_arguments):
    parser = argparse.ArgumentParser()
    #define subparsers and add arguments to them
    subparsers = parser.add_subparsers(dest='task')

    # add action="store_true" to each argument if it is a flag
    for arg in inspect.signature(parser).parameters:
        if argparse.ArgumentParser._get_optional_google_type_arg(parser, arg) is not None:
            setattr(parser, arg, parser._get_optional_google_type_arg(parser, arg))

    parsed_arguments = parser.parse_args(unparsed_arguments)
    return { task.subparser_name: vars(task) for task in parser._actions }

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    return collections.defaultdict(argparse.Namespace, argparse.ArgumentParser().parse_known_args(unparsed_arguments))

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed = {}
    remaining = []
    for arg in unparsed_arguments:
        if not parsed:
            args parsed[subparsers[arg].name] = subparsers[arg].parse_known_args(arg.split())
            parsed[subparsers[arg].name].args = args[0].args
            global_vars = vars(args[0])
            for key in global_vars:
                if key not in subparsers[arg].options and key not in subparsers[arg].additional_options and key not in subparsers[arg].arg_defaults:
                    remaining.append(global_vars[key])
        else:
            remaining.append(arg)
    return parsed, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    result = {}
    remaining_args = []
    for parser in subparsers.values():
        parsed_args = parser.parse_args(unparsed_arguments)
        if parsed_args:
            result[parser.prog] = parsed_args
        remaining_args.extend(parsed_args.args)
    return result, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = unparsed_arguments

    for name, parser in subparsers.items():
        if name in parsed_args:
            continue  # already parsed
        parsed_args[name], remaining_args = parser.parse_known_args(remaining_args)

    return parsed_args, remaining_args

def make_parsers():
    """
    Build a top-level parser and its subparsers and return them as a tuple.
    """
    return (ArgumentParser(description="Command-line based application"), subparsers=True)

