                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    merged = {}  # dictionary to hold the merged configuration data
    for node_key, node_value in nodes:
        if isinstance(node_key, ScalarNode):
            if node_key.tag == 'tag:yaml.org,2002:str':
                merged[node_key.value] = join(merged.get(node_key.value), node_value.value)
            else:
                # for non-string keys, we use user-defined __setitem__ implementation,
                # or raise an error if the key is not of the expected type
                merged[node_key.value] = join(merged.get(node_key.value), node_value)
        elif isinstance(node_key, MappingNode):
            if node_key.tag == 'tag:yaml.org,2002:map':
                # recursively merge mappings
                merged[node_key.value] = {**merged.get(node_key.value, {}), **node_value.value}
            else:
                # for non-mapping keys, we use user-defined __setitem__ implementation,
                # or raise an error if the key is not of the expected type
                merged[node_key.value] = {**merged.get(node_key.value, {}), **node_value}

    return [ScalarNode(tag='tag:yaml.org,2002:str', value=merged[key]) for key in sorted(merged)]

