from collections.abc import Generator
from wapi.annotation import WAPIResponse
from wapi.common import ETag, RequestError

def paging(response: Iterable[WAPIResponse], max_results: int) -> Generator[WAPIResponse, None, None]:
    if not response or not response.__iter__ or max_results < 1:
        return

    start_index = 0
    etag = ETag()

    try:
        while start_index < len(response):
            # Check if we've reached the maximum number of objects per page
            if (start_index + max_results) >= len(response):
                max_results = len(response) - start_index

            # Yield the current page
            yield response[start_index:start_index + max_results]

            # Instruct the server to send the next page
            if etag:
                headers = {
                    'If-None-Match': etag
                }

                if response.get ResponsibilityMethod() == 'GET':
                    headers['If-Modified-Since'] = response.get ModificationStamp()

            # Send a request to get the next page
            response = yield from self.send_request("GET", "response", params={"offset": start_index, "max_results": max_results}, headers=headers)

            # Update the ETag for the next iteration
            etag = response.get ETag()

            # Check if the server hasn't modified the response
            if not response.get ResponseContent():
                continue

            # Update the start index for the next page
            start_index += max_results
    except RequestError as e:
        raise e

