def _replace_url_args(url, url_args):
    import urllib.parse

    parsed_url = urllib.parse.urlparse(url)
    query_params = parsed_url.query

    if query_params:
        query_dict = urllib.parse.parse_qs(query_params)

        for param_name, param_value in url_args.items():
            if param_name in query_dict and query_param_value in query_dict[param_name]:
                query_dict[param_name].remove(query_param_value)

        new_query = '&'.join([f"{key}={value}" for key, value in query_dict.items()])
    else:
        new_query = 'None'

    new_url = urllib.parse.urlunparse(
        (parsed_url.scheme, parsed_url.netloc, parsed_url.path, parsed_url.params, new_query, parsed_url.fragment)
    )

    return new_url

