def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.

    Arguments:
        number (int): The number to convert
        alphabet (List[str]): The alphabet to use for conversion
        padding (Optional[int]): Optional number of leading zeros to add

    Returns:
        str
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    if number < 0:
        raise ValueError("Number must be non-negative")

    if padding is not None:
        if number < 10 ** padding:
            return "0" * padding + str(number)
        elif number < 10 ** padding + len(alphabet):
            return alphabet[number % len(alphabet)]
        else:
            raise ValueError("Number is too large to be converted to string using provided alphabet")

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        digits.extend(['0'] * (padding - len(digits)))
        return ''.join(digits)[::-1]
    else:
        return ''.join(digits[::-1])

