def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp"):
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Use subprocess to run the archive extracting commands
    try:
        # Uncompress the archive using the command based on the file type
        # Python allows using parallelized file operations, most archive formats are supported.
        if filename:
            sub = subprocess.run(['tar', '-xzvf', filename], cwd=tmp_path, check=True)
            if sub.returncode == 0:
                # If the archive was successfully unzipped, return the file system path
                return str(sub.stdout)
        else:
            sub = subprocess.run(['xar', '-L', '-xvf', archive_path], cwd=tmp_path, check=True)
            if sub.returncode == 0:
                # If the archive was successfully unarchived, return the file system path
                return str(sub.stdout)
        raise ValueError(f'Failed to extract {archive_path}')
    except subprocess.CalledProcessError as e:
        print(f'Error encountered while extracting archive: {e}')
        raise ValueError('Failed to prepare repository from archive. Make sure the archive path is correct.')

