        return None

    if ' ' in frequency:
        number, unit = frequency.split()
    else:
        number = frequency
        unit = 'day'

    try:
        number = int(number)
    except ValueError:
        raise ValueError("Invalid frequency format. Usage: [number] [unit] (e.g., '3 weeks')")

    unit = unit.lower()

    if unit == 'day':
        return datetime.timedelta(days=number)
    elif unit == 'week':
        return datetime.timedelta(weeks=number)
    elif unit == 'month':
        return datetime.timedelta(days=number * 30)
    elif unit == 'year':
        return datetime.timedelta(days=number * 365)
    else:
        raise ValueError(f"Unsupported unit '{unit}'. Valid units are 'day', 'week', 'month', 'year'.")

