def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    for s, p, o in graph:
        if p == prop:
            if o not in roots:
                roots.add(o)

    return roots

def find_roots(graph:(rdflib.Graph, "Node"), prop: ("URIRef", "Node"), roots: Optional["Set[Node]"] = None) -> "Set[Node]":
    if roots is None:
        roots = set()

    for child in graph.subjects(prop, None):
        if child not in roots:
            roots.add(child)
            roots.update(find_roots(graph, prop, roots))

    return roots

