def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        supported_versions = cls.parser_info().supported_versions
        if protocol_version is None:
            return {version: cls.protocol_handler_for_version(version) for version in supported_versions}
        else:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            if protocol_version not in supported_versions:
                raise ValueError("Protocol version is not supported")
            return {protocol_version: cls.protocol_handler_for_version(protocol_version)}

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is None:
            return {version: handler for version, handler in cls._handlers.items()}

        try:
            version_tuple = tuple(int(x) for x in protocol_version.split('.'))
        except ValueError:
            raise TypeError('Protocol version must be passed in a tuple (e.g. (3, 5)).')

        handler_version = version_tuple in cls._handlers
        if handler_version and protocol_version == cls._handlers[version_tuple]:
            return {version_tuple: handler}
        elif handler_version:
            warning("Protocol version {} is not supported, using version {}.".format(protocol_version, cls._handlers[version_tuple].__version__))
            return {version_tuple: handler}
        else:
            return {}

