class DateTimeParser:
    def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
        try:
            return datetime.strptime(timestr, self.FORMAT)
        except ValueError:
            if default and isinstance(default, datetime) and not ignoretz:
                tz = default.tzinfo
            elif not tzinfos:
                tz = timezone.utc
            elif tzinfos is not None:
                tz = tzinfos.get("UTC", timezone.utc)
            date = datetime.strptime(timestr, self.FORMAT, tz=tz)
            if not ignoretz:
                return date
            return date.replace(tzinfo=None)

