class TimeZoneAwareDateTime(datetime):
    def __init__(self, *args, tzinfo, **kwargs):
        super().__init__(*args, tzinfo=tzinfo, **kwargs)

    def to_hashable_str(self, include_tz=False, with_timezone=False, add_fold_state=False):
        if include_tz:
            formatted_str = self.strftime('%Y-%m-%d %H:%M:%S %Z')
        else:
            formatted_str = self.strftime('%Y-%m-%d %H:%M:%S')

        if with_timezone:
            formatted_str += ' (UTC)'

        if add_fold_state:
            if self.isambiguous():
                fold_state = ' Fold'
            else:
                fold_state = ''
            formatted_str += fold_state

        return formatted_str

