def addable(Class, parent, set=None, raiseexceptions=True):
    if not parent.__class__.accepts(Class, raiseexceptions, parent):
        return False

    if Class.OCCURRENCES > 0:
        count = parent.count(Class,None,True,[True, AbstractStructureElement])
        if count >= Class.OCCURRENCES:
            if raiseexceptions:
                raise DuplicateAnnotationError("Unable to add another object of type " + Class.__name__ + " to " + parent.__class__.__name__ + ". There are already " + str(count) + " instances of this class.")
            else:
                return False

    if Class.OCCURRENCES_PER_SET > 0 and set and Class.REQUIRED_ATTRIBS and Attrib.CLASS in Class.REQUIRED_ATTRIBS:
        count = parent.count(Class,set,True, [True, AbstractStructureElement])
        if count >= Class.OCCURRENCES_PER_SET:
            if raiseexceptions:
                raise DuplicateAnnotationError("Unable to add another object set " + set + " and type " + Class.__name__ + " to " + parent.__class__.__name__ + ". There are already " + str(count) + " instances of this class, which is the maximum for the set.")
