        // Verify the public key for the claim
        if (!PublicKey.isValid(publicKey, claimedIssuerSign)) {
            return false;
        }

        // Verify the actual signature against the sender's private key
        return Crypto.verifySignature(doc, publicKey, signature);
    } catch (Exception e) {
        // Handle exceptions, e.g., unable to connect to server, etc.
        e.printStackTrace();
        return false;
    }
}

