def validate_from_content(spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise ValueError("Invalid input: Spec content is None.")

    required_fields = ["class", "id", "text", "attributes"]
    for field in required_fields:
        if field not in spec_content:
            raise YAMLInvalidRequest(f"Missing required field '{field}' in the spec content.")

    try:
        data = {
            field: value
            for field, value in spec_content.items()
        }
    except YAMLInvalidRequest as e:
        raise ValueError(f"Error parsing spec content: {e}")

    return data

