def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not yaml_file:
            raise IRValidatorException("No YAML file specified")

        try:
            with open(yaml_file, 'r', encoding='utf-8') as file:
                data = yaml.safe_load(file)
        except FileNotFoundError:
            raise IRValidatorException("File " + yaml_file + " not found")
        except yaml.YAMLError as e:
            raise IRValidatorException("Invalid YAML format in file: " + str(e))

        mandatory_fields = ['field1', 'field2', 'field3']  # Replace with actual required fields
        for field in mandatory_fields:
            if field not in data:
                raise IRValidatorException("Mandatory field '{}' not found in YAML file".format(field))

        return data

def validate_from_file(cls, yaml_file=None):
