class InvalidArgsError(Exception):
    """Exception raised when arguments are out of the valid range."""

def validate_min_max_args(self, args: List[int]) -> None:
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    minimum = self.min_value
    maximum = self.max_value

    if minimum is not None and args[0] < minimum:
        raise InvalidArgsError("Minimum value is %d but received %d" % (minimum, args[0]))

    if maximum is not None and args[0] > maximum:
        raise InvalidArgsError("Maximum value is %d but received %d" % (maximum, args[0]))

def get_nested_custom_and_control_args(self, args):
    flat_args_dict = {}

    nested_args = []
    control_args = []

    for arg in args:
        if arg.startswith("--custom-"):
            flat_args_dict["custom"] = arg[len("--custom-"):]
        elif arg.startswith("--nested-"):
            nested_args.append(arg[len("--nested-"):])
        else:
            flat_args_dict[arg] = True

    return flat_args_dict, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if isinstance(args, list):
        for arg in args:
            if isinstance(arg, dict):
                if 'control' in arg:
                    for key, value in arg.items():
                        control_args[key] = value
                elif 'nested' in arg:
                    for key, value in arg.items():
                        nested_args[key] = value
            elif isinstance(arg, str):
                nested_args[arg] = True
            else:
                raise ValueError("Invalid argument type: %s" % type(arg))
    else:
        raise ValueError("Invalid args type: %s" % type(args))

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
