    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    for arg in args:
        if "control-" in arg:
            control_args[f"control_{arg.replace('control-', '')}"] = True
        elif "nested-" in arg:
            nested_args[f"nested_{arg.replace('nested-', '')}"] = True
        else:
