def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
    workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
    directly to Ansible.
    """
    if not ir_workspace or not ir_plugin or not playbook_path:
        raise ValueError("All parameters are required: ir_workspace, ir_plugin, playbook_path")

    if verbose is not None:
        default_args = "--quiet" if verbose == 0 else (("--verbose" if verbose == 1 else (("--debug" if verbose == 2 else "--verbose 2"))))
    else:
        default_args = "--quiet"

    extra_vars = extra_vars or {}
    ansible_args = ansible_args or {}

    additional_args = {**extra_vars, **ansible_args}

    os.system(f"ansible-playbook -i {ir_workspace.inventory_path} {ir_workspace.host_vars_path} {ir_workspace.extra_vars_path} -e {ir_plugin.extra_vars_path} {default_args} {playbook_path}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key in values_dict:
        try:
            value_type = type(values_dict[key])
            if value_type is str or value_type is None:
                pass
            elif value_type is int:
                values_dict[key] = int(values_dict[key])
            elif value_type is float:
                values_dict[key] = float(values_dict[key])
            elif value_type is bool:
                if values_dict[key].lower() in ('yes', 'true'):
                    values_dict[key] = True
                elif values_dict[key].lower() in ('no', 'false'):
                    values_dict[key] = False
                else:
                    raise ValueError(f"Invalid value for key '{key}': {values_dict[key]}")
            elif value_type in [list, tuple]:
                try:
                    values_dict[key] = [value_type(ele) for ele in values_dict[key]]
                except ValueError as e:
                    raise ValueError(f"Invalid list/tuple value for key '{key}': {e}")
            else:
                raise ValueError(f"Unsupported type for key '{key}' with value '{values_dict[key]}': {type(values_dict[key])}")
        except KeyError:
            raise KeyError(f"Missing key '{key}' in the values_dict")

