def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        if value and isinstance(value, str):
            if parser_name == 'main':
                if key in ['--int', '--int-list']:
                    values_dict[key] = int(value)
                elif key == '--float':
                    values_dict[key] = float(value)
                elif key == '--bool':
                    values_dict[key] = bool(value)
                elif key == '--str':
                    values_dict[key] = value
                elif key == '--path':
                    values_dict[key] = os.path.abspath(value)
                elif key == '--date':
                    values_dict[key] = datetime.datetime.strptime(value, '%Y-%m-%d')
                elif key == '--time':
                    values_dict[key] = datetime.datetime.strptime(value, '%H:%M:%S')
            elif parser_name == 'spoof':
                if key in ['--ip', '--ipv4', '--ipv6']:
                    values_dict[key] = socket.aton(value if ':' not in value else value.split(':')[1])
                elif key == '--mac':
                    values_dict[key] = socket.inet_aton(value)
                elif key == '--vlan':
                    values_dict[key] = int(value)
                elif key == '--string':
                    values_dict[key] = value
                elif key == '--path':
                    values_dict[key] = os.path.abspath(value)
                elif key == '--md5':
                    values_dict[key] = hashlib.md5(value.encode()).hexdigest()
                elif key == '--sha1':
                    values_dict[key] = hashlib.sha1(value.encode()).hexdigest()
                elif key == '--sha256':
                    values_dict[key] = hashlib.sha256(value.encode()).hexdigest()
            elif parser_name == 'analyzer':
                if key == '--format':
                    values_dict[key] = value.lower()
                elif key in ['--service', '--executable', '--protocols', '--port', '--port-range', '--tcp-auth', '--http-auth']:
                    values_dict[key] = value.split(',') if ',' in value else [value]
            elif parser_name == 'log':
                if key == '--facility':
                    values_dict[key] = re.match('(,)'.join(MockList), value).group(0).replace(',','')
            elif parser_name in ['config', 'setupconfig']:
                if key == '--port':
                    values_dict[key] = int(value)
                elif key == '--network':
                    values_dict[key] = value
        elif value and isinstance(value, list):
            values_dict[key] = [convert_arg(elem, parser_name) for elem in value]

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

        :param plugin_dir: A path to the plugin's dir
        :return: A flatten dictionary contains the plugin's properties
        """
    import os
    import json

    spec = json.load(open(os.path.join(plugin_dir, 'spec.json')))
    flatten_dict = {}

    for key, value in spec.items():
        if isinstance(value, dict):
           flatten_dict[key] = get_plugin_spec_flatten_dict(value)
        else:
            flatten_dict[key] = value

    return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os

    flatten_dict = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                with open(file_path) as f:
                    spec = json.load(f)
                    for key, value in spec.items():
                        full_key = os.path.relpath(root, plugin_dir) + '//' + key
                        flatten_dict[full_key] = value

    return flatten_dict

